    private void tasks()throws Exception{
        progress("native taskbar hold and Task Manager actions");ui(()->home.open("@notes"));DesktopWindow notes=window("@notes");EditText editor=(EditText)find(notes,v->"Notepad text".equals(v.getContentDescription()));ui(()->editor.setText("Task polish keeps this note"));ui(()->home.open("@calendar"));DesktopWindow calendar=window("@calendar");tap(find(calendar,v->"Minimize window".equals(v.getContentDescription())),60);await(()->calendar.getVisibility()!=View.VISIBLE,"Calendar minimized");
        bar("Start Task Manager");await(()->window("@taskmanager")!=null,"Taskbar hold opens the actual manager");DesktopWindow manager=window("@taskmanager");check(find(manager,v->"Task: Notepad".equals(v.getContentDescription()))!=null,"Lists Nth window");check(find(manager,v->v instanceof TextView&&"Minimized".contentEquals(((TextView)v).getText()))!=null,"Minimized status uses real window state");shot("vista-task-manager.png");
        tap(find(manager,v->"Task: Notepad".equals(v.getContentDescription())),60);tap(text(manager,"Switch To"),60);await(()->manager.getVisibility()!=View.VISIBLE&&notes.active(),"Switch To restores selected window and minimizes manager");check(editor.getText().toString().equals("Task polish keeps this note"),"Same editor survives switching");ui(()->home.open("@taskmanager"));tap(find(manager,v->"Task: Calendar".equals(v.getContentDescription())),60);tap(text(manager,"End Task"),60);await(()->calendar.getParent()==null,"End Task closes selected Nth window");check(store.prefs.getString("note","").equals("Task polish keeps this note"),"Ending another task keeps the note");
        tap(find(manager,v->"Task Manager Performance".equals(v.getContentDescription())),60);TaskManagerPanel panel=(TaskManagerPanel)manager.body;int count=panel.sampleCount();await(()->panel.sampleCount()>count,"Performance receives a real sample");check(find(manager,v->v instanceof TextView&&((TextView)v).getText().toString().contains("available /"))!=null,"Displays actual device memory");shot("vista-task-performance.png");tap(find(manager,v->"Minimize window".equals(v.getContentDescription())),60);int hidden=panel.sampleCount();Thread.sleep(2300);check(panel.sampleCount()==hidden,"Hidden manager stops performance timer");ui(()->home.open("@taskmanager"));await(()->panel.sampleCount()>hidden,"Restored manager resumes samples");tap(text(manager,"View"),60);menuTap("Pause updates");int paused=panel.sampleCount();Thread.sleep(2300);check(panel.sampleCount()==paused,"Pause updates stops the real timer");tap(text(manager,"View"),60);menuTap("Pause updates");
        int before=panel.sampleCount();shell("am start -W -n com.nthexperience.desktop.fixture/.TaskActivity");Thread.sleep(200);int stopped=panel.sampleCount();Thread.sleep(2200);check(panel.sampleCount()==stopped,"Real background Activity stops sampling");shell("am start -W -n "+new ComponentName(getTargetContext(),MainActivity.class).flattenToString());await(()->home.hasWindowFocus(),"Returns from real background Activity");await(()->panel.sampleCount()>before,"Real Activity resume restarts samples");
        check(StartSearch.find(store,new ArrayList<>(),"task manager").stream().filter(r->r.id.equals("setting:open:@taskmanager")).count()==1,"Task Manager has one searchable canonical route");List<String> quick=store.quickLaunch();List<String> test=new ArrayList<>(quick);if(!test.contains("@taskmanager"))test.add("@taskmanager");store.quickLaunch(test);DesktopBackup.parse(DesktopBackup.snapshot(store).toString());store.quickLaunch(quick);close("@taskmanager");
    }
    private void windowCommands()throws Exception{
        progress("caption double tap and shared taskbar/window menus");ui(()->home.open("@notes"));DesktopWindow notes=window("@notes");View title=find(notes,v->v.getContentDescription()!=null&&v.getContentDescription().toString().startsWith("Notepad. Drag"));boolean max=notes.maximized();
        await(()->home.hasWindowFocus()&&title.isShown()&&!title.isLayoutRequested(),"Notepad caption is ready for touch");
        doubleTap(title);
        Thread.sleep(ViewConfiguration.getDoubleTapTimeout()+60L);
        if(notes.maximized()==max)doubleTap(title);
        await(()->notes.maximized()!=max,"Double tapping caption toggles maximize");tap(find(notes,v->"Window menu".equals(v.getContentDescription())),60);awaitNode("Restore");awaitNode("Close");shot("vista-window-menu.png");menuTap("Minimize");await(()->notes.getVisibility()!=View.VISIBLE,"Caption menu minimizes");
        View button=find(v->"Restore Notepad".equals(v.getContentDescription()));tap(button,700);menuTap("Taskbar item commands");menuTap("Restore");await(()->notes.isShown(),"Taskbar system menu restores minimized window");ui(()->home.open("@calendar"));DesktopWindow calendar=window("@calendar");tap(find(v->"Minimize Calendar".equals(v.getContentDescription())),700);menuTap("Taskbar item commands");menuTap("Close");await(()->calendar.getParent()==null,"Taskbar Close performs actual window cleanup");
    }
    private void arrangements()throws Exception{
        progress("native arrangement commands and undo in a real landscape work area");ui(()->home.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE));await(()->root.getWidth()>root.getHeight(),"Landscape ready");ui(()->home.open("@notes"));ui(()->home.open("@calendar"));DesktopWindow notes=window("@notes"),calendar=window("@calendar");if(!notes.maximized())tap(find(notes,v->"Maximize or restore window".equals(v.getContentDescription())),60);JSONObject before=notes.geometry();
        bar("Show Windows Side by Side");await(()->notes.getWidth()<root.getWidth()*.7&&calendar.getWidth()<root.getWidth()*.7,"Side by Side divides the real wide workspace");check(Math.abs(notes.getY()-calendar.getY())<2&&(Math.abs(notes.getX()+notes.getWidth()-calendar.getX())<3||Math.abs(calendar.getX()+calendar.getWidth()-notes.getX())<3),"Side by Side has aligned rows and adjacent edges");shot("vista-windows-side.png");bar("Undo Window Arrangement");await(notes::maximized,"Undo restores maximized state");check(notes.geometry().toString().equals(before.toString()),"Undo retains exact normal geometry");
        bar("Show Windows Stacked");
        int area=((View)notes.getParent()).getHeight();
        await(()->!notes.maximized()&&!notes.isLayoutRequested()&&!calendar.isLayoutRequested(),"Stacked finishes applying window geometry");
        if(area>=Aero.dp(home,380)){check(Math.abs(notes.getX()-calendar.getX())<3&&(Math.abs(notes.getY()+notes.getHeight()-calendar.getY())<3||Math.abs(calendar.getY()+calendar.getHeight()-notes.getY())<3),"Stacked aligns rows when both fit");}else check(notes.getWidth()>=Aero.dp(home,240)&&calendar.getWidth()>=Aero.dp(home,240),"Short landscape workspaces retain usable window width");check(notes.getX()>=0&&calendar.getY()>=0&&notes.getY()+notes.getHeight()<=area+2&&calendar.getY()+calendar.getHeight()<=area+2,"Arranged windows stay in safe work area");bar("Cascade Windows");await(()->Math.abs(calendar.getX()-notes.getX())>4&&Math.abs(calendar.getY()-notes.getY())>4,"Cascade shows both actual captions");shot("vista-windows-cascade.png");bar("Undo Window Arrangement");close("@calendar");
        ui(()->home.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT));await(()->root.getWidth()<root.getHeight(),"Portrait ready");
    }
    private void restoration()throws Exception{
        progress("Show Desktop restores only its hidden windows across recreation");ui(()->home.open("@calendar"));DesktopWindow calendar=window("@calendar"),notes=window("@notes");tap(find(calendar,v->"Minimize window".equals(v.getContentDescription())),60);bar("Show the Desktop");DesktopWindow hiddenNote=notes;await(()->hiddenNote.getVisibility()!=View.VISIBLE,"Show Desktop hides visible note");bar("Show Open Windows");await(notes::isShown,"Show Open Windows restores note");check(calendar.getVisibility()!=View.VISIBLE,"A previously minimized window stays minimized");
        bar("Show the Desktop");recreate();notes=window("@notes");calendar=window("@calendar");check(notes!=null&&!notes.isShown(),"Hidden note restored as hidden after recreation");bar("Show Open Windows");DesktopWindow restoredNotes=notes;await(restoredNotes::isShown,"Show Desktop restore set survives recreation");check(!calendar.isShown(),"Old minimized state survives recreation");ui(()->home.open("@taskmanager"));tap(find(window("@taskmanager"),v->"Task Manager Performance".equals(v.getContentDescription())),60);recreate();check(((TaskManagerPanel)window("@taskmanager").body).state().optString("tab").equals("Performance"),"Manager restores actual selected tab");close("@taskmanager");close("@calendar");
    }
    private void external()throws Exception{
        progress("external Android entry and real App Info screen");String id="com.nthexperience.desktop.fixture/.TaskActivity";ui(()->home.open(id));Thread.sleep(400);shell("am start -W -n "+new ComponentName(getTargetContext(),MainActivity.class).flattenToString());await(()->home.hasWindowFocus(),"Returns from actual separate-UID app");ui(()->home.open("@taskmanager"));DesktopWindow manager=window("@taskmanager");menuTap("Task Manager Applications");await(()->find(manager,v->v instanceof TextView&&"Recently opened".contentEquals(((TextView)v).getText()))!=null,"External entry is labelled Recently opened");await(()->find(manager,v->"Task: Task switch probe".equals(v.getContentDescription()))!=null,"Exact external fixture row exists");for(int attempt=0;attempt<3&&text(manager,"App Info…")==null;attempt++){menuTap("Task: Task switch probe");}await(()->text(manager,"App Info…")!=null&&text(manager,"End Task")==null,"External action clearly uses App Info");Intent expected=new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:com.nthexperience.desktop.fixture"));boolean hasSettings=expected.resolveActivity(home.getPackageManager())!=null;java.util.concurrent.atomic.AtomicReference<Intent> requested=new java.util.concurrent.atomic.AtomicReference<>();ActivityMonitor monitor=new ActivityMonitor(){@Override public ActivityResult onStartActivity(Intent intent){if(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS.equals(intent.getAction()))requested.set(new Intent(intent));return null;}};addMonitor(monitor);try{menuTap("App Info…");await(()->requested.get()!=null,"Native button dispatches the real App Info intent");check(expected.getData().equals(requested.get().getData()),"App Info targets the actual selected package");if(hasSettings){Thread.sleep(400);String activity=shell("dumpsys activity activities");check(activity.contains("com.android.settings")&&activity.contains("APPLICATION_DETAILS_SETTINGS"),"App Info opens Android's actual details Activity");shell("input keyevent KEYCODE_BACK");await(()->home.hasWindowFocus(),"Returns from App Info");}else{check(home.hasWindowFocus(),"ATD image without a Settings app handles the unavailable action without leaving the launcher");progress("App Info intent and exact package verified; this Android image has no Settings Activity");}}finally{removeMonitor(monitor);}shell("am start -W -n com.nthexperience.desktop.fixture/.TaskActivity --ez finish-task true");shell("am start -W -n "+new ComponentName(getTargetContext(),MainActivity.class).flattenToString());await(()->home.hasWindowFocus(),"Fixture cleanup returns home");
    }
    private void recreate()throws Exception{resumed.clear();MainActivity old=home;ui(home::recreate);long until=SystemClock.uptimeMillis()+12000;MainActivity next=null;while(SystemClock.uptimeMillis()<until){MainActivity a=resumed.poll(500,TimeUnit.MILLISECONDS);if(a!=null&&a!=old){next=a;break;}}check(next!=null,"Real Activity recreation completed");home=next;root=home.getWindow().getDecorView();await(()->home.hasWindowFocus(),"Recreated desktop focused");await(()->window("@notes")!=null,"Session windows restored");}
    private void bar(String command)throws Exception{tap(find(v->"Taskbar commands".equals(v.getContentDescription())),700);awaitNode("Start Task Manager");if(command.equals("Start Task Manager"))shot("vista-taskbar-menu.png");menuTap(command);}
    private DesktopWindow window(String id){return (DesktopWindow)findAll(root,v->v instanceof DesktopWindow&&id.equals(((DesktopWindow)v).toolId));}
    private void close(String id)throws Exception{DesktopWindow w=window(id);if(w!=null){if(!w.isShown())ui(()->home.open(id));tap(find(w,v->"Close window".equals(v.getContentDescription())),60);}}
    private View text(View base,String text){return find(base,v->v instanceof TextView&&text.contentEquals(((TextView)v).getText()));}
    private View find(Predicate<View> match){return find(root,match);}private View find(View v,Predicate<View> match){if(v==null||!v.isShown())return null;if(match.test(v))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View result=find(((ViewGroup)v).getChildAt(i),match);if(result!=null)return result;}return null;}
    private View findAll(View v,Predicate<View> match){if(v==null)return null;if(match.test(v))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View result=findAll(((ViewGroup)v).getChildAt(i),match);if(result!=null)return result;}return null;}
    private void tap(View v,long hold)throws Exception{check(v!=null,"Native touch target exists");await(()->home.hasWindowFocus(),"Focused native target");ui(()->v.requestRectangleOnScreen(new Rect(0,0,v.getWidth(),v.getHeight()),true));getUiAutomation().waitForIdle(150,2500);Rect r=new Rect();check(v.isEnabled()&&v.getGlobalVisibleRect(r)&&!r.isEmpty(),"Native target has visible bounds: "+v.getContentDescription());long t=SystemClock.uptimeMillis();input(t,MotionEvent.ACTION_DOWN,r.exactCenterX(),r.exactCenterY());Thread.sleep(hold);input(t,MotionEvent.ACTION_UP,r.exactCenterX(),r.exactCenterY());Thread.sleep(100);}
    private void doubleTap(View v)throws Exception{Rect r=new Rect();check(v.getGlobalVisibleRect(r),"Caption has visible bounds");for(int i=0;i<2;i++){long t=SystemClock.uptimeMillis();input(t,MotionEvent.ACTION_DOWN,r.exactCenterX(),r.exactCenterY());Thread.sleep(35);input(t,MotionEvent.ACTION_UP,r.exactCenterX(),r.exactCenterY());Thread.sleep(60);}}
    private void input(long down,int action,float x,float y){MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x,y,0);e.setSource(InputDevice.SOURCE_TOUCHSCREEN);check(getUiAutomation().injectInputEvent(e,true),"Native input injected");e.recycle();}
    private void menuTap(String text)throws Exception{awaitNode(text);getUiAutomation().waitForIdle(150,2500);AccessibilityNodeInfo node=node(text);check(node!=null&&node.isEnabled(),"Enabled menu command: "+text);Rect r=new Rect();node.getBoundsInScreen(r);long t=SystemClock.uptimeMillis();input(t,MotionEvent.ACTION_DOWN,r.exactCenterX(),r.exactCenterY());Thread.sleep(55);input(t,MotionEvent.ACTION_UP,r.exactCenterX(),r.exactCenterY());Thread.sleep(150);}
    private void awaitNode(String text)throws Exception{long end=SystemClock.uptimeMillis()+8000;while(SystemClock.uptimeMillis()<end){if(node(text)!=null)return;Thread.sleep(100);}throw new AssertionError("Native menu node: "+text);}
    private AccessibilityNodeInfo node(String text){return node(getUiAutomation().getRootInActiveWindow(),text);}private AccessibilityNodeInfo node(AccessibilityNodeInfo n,String text){if(n==null)return null;if(text.contentEquals(n.getText()==null?"":n.getText())||text.contentEquals(n.getContentDescription()==null?"":n.getContentDescription()))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo r=node(n.getChild(i),text);if(r!=null)return r;}return null;}
    private void ui(Runnable r){runOnMainSync(r);try{Thread.sleep(80);}catch(InterruptedException e){throw new AssertionError(e);}}
    private void await(BooleanSupplier condition,String text)throws Exception{long end=SystemClock.uptimeMillis()+12000;while(SystemClock.uptimeMillis()<end){boolean[] ready={false};runOnMainSync(()->ready[0]=condition.getAsBoolean());if(ready[0])return;Thread.sleep(100);}throw new AssertionError(text);}
    private String shell(String command)throws Exception{try(ParcelFileDescriptor fd=getUiAutomation().executeShellCommand(command);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(fd);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);return out.toString("UTF-8");}}
    private void shot(String name)throws Exception{getUiAutomation().waitForIdle(150,2500);Bitmap image=getUiAutomation().takeScreenshot();check(image!=null,"Screenshot available");try(FileOutputStream out=getTargetContext().openFileOutput(name,0)){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
    private void dump(AccessibilityNodeInfo n,StringBuilder out,int depth){if(n==null||depth>24)return;out.append(depth).append(' ').append(n.getText()).append(" / ").append(n.getContentDescription()).append('\n');for(int i=0;i<n.getChildCount();i++)dump(n.getChild(i),out,depth+1);}
    private void progress(String text){Bundle result=new Bundle();result.putString("stream","CHECK: "+text+"\n");sendStatus(1,result);}private static void check(boolean value,String text){if(!value)throw new AssertionError(text);}
